}","new_string":"/**
 * Read one policy file.
 * @param {string} path - the policy file's workspace path, as the argument gave it.
 * @returns {{limit?: {starts: number, window: number}, retry?: {max: number, base: number}}} the policy it sets.
 * @throws {PolicyError} when the file is unreadable or a line is malformed.
 */
export function readPolicy(path) {
  let content
  try {
    content = readFileSync(path, 'utf8')
  } catch {
    throw new PolicyError(`cannot read policy ${path}`)
  }

  // Parse the policy file
  const lines = splitLines(content)
  const policy = {}

  for (const [index, raw] of lines.entries()) {
    const lineNum = index + 1
    const text = raw.trim()
    // Skip empty lines and comments
    if (text === '' || text.startsWith('#')) continue

    const words = text.split(/\s+/u)

    try {
      // Check if it's a policy directive
      if (policyDirective(lineNum, words, policy)) continue
    } catch (error) {
      if (error instanceof LogError) {
        // Convert LogError to PolicyError with file prefix
        throw new PolicyError(`${path}: line ${lineNum}: ${error.message}`)
      }
      throw error
    }

    // If it's not a policy directive, it's unknown
    throw new PolicyError(`${path}: line ${lineNum}: unknown directive ${words[0]}`)
  }

  return policy
}"}

